package com.governai.decision;
import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/decisions") public class DecisionController {private final DecisionService service;private final com.governai.governance.GovernanceDecisionService governanceService;public DecisionController(DecisionService service,com.governai.governance.GovernanceDecisionService governanceService){this.service=service;this.governanceService=governanceService;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public DecisionRequestResponse create(@Valid @RequestBody DecisionRequestPayload p){return service.create(p);}@GetMapping("/{id}")public DecisionRequestResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping public List<DecisionRequestResponse> list(@RequestParam(required=false) UUID organizationId,@RequestParam(required=false) DecisionStatus status){return service.list(organizationId,status);}@PutMapping("/{id}")public DecisionRequestResponse update(@PathVariable UUID id,@Valid @RequestBody DecisionRequestPayload p){return service.update(id,p);}@PatchMapping("/{id}/status")public DecisionRequestResponse status(@PathVariable UUID id,@Valid @RequestBody DecisionStatusPayload p){return service.updateStatus(id,p.status());}@PostMapping("/{id}/analyze")public com.governai.governance.GovernanceDecisionResponse analyze(@PathVariable UUID id){return governanceService.analyze(id);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable UUID id){service.delete(id);}@PostMapping("/{id}/evidence")@ResponseStatus(HttpStatus.CREATED)public EvidenceResponse evidence(@PathVariable UUID id,@Valid @RequestBody EvidencePayload p){return service.addEvidence(id,p);}@GetMapping("/{id}/evidence")public List<EvidenceResponse> evidence(@PathVariable UUID id){return service.evidence(id);}@PostMapping("/{id}/recommendations")@ResponseStatus(HttpStatus.CREATED)public RecommendationResponse recommendation(@PathVariable UUID id,@Valid @RequestBody RecommendationPayload p){return service.addRecommendation(id,p);}@GetMapping("/{id}/recommendations")public List<RecommendationResponse> recommendations(@PathVariable UUID id){return service.recommendations(id);}@PostMapping("/{id}/approvals")@ResponseStatus(HttpStatus.CREATED)public ApprovalResponse approve(@PathVariable UUID id,@Valid @RequestBody ApprovalPayload p){return service.approve(id,p);}@GetMapping("/{id}/approvals")public List<ApprovalResponse> approvals(@PathVariable UUID id){return service.approvals(id);}}
